/* H1 S1: new-position recovery after each S0 trigger; delays [30, 120, 300] s (120 s main). Rendered by build_h1_s1.py. */ /* 3 A-week events from RT/case_timing/h1_events_A.csv. Partitions 2026-06-01 .. 2026-07-10 (curve TradeEvent only to 2026-06-17; */ /* see curve_cut_risk). No SQL credit stop: */ /* the platform per-execution cap applies. Recovery excludes the fixed 0.004 deduction (applied in analysis). */ WITH ev(mint, sig_time, sig_slot, sig_txi) AS (SELECT * FROM (VALUES ('B1C2xfcUajAAU8n3zfuXqXvvALRw8cB5sPzNB5ktpump', CAST('2026-06-02T01:10:13Z' AS TIMESTAMPTZ), CAST('423707026' AS BIGINT), 86), ('5i1SVh2AwSFgdYuhFnM2K74n6MxBjxjWKcP3vHAcpump', CAST('2026-06-03T06:21:28Z' AS TIMESTAMPTZ), CAST('423971339' AS BIGINT), 39), ('BUvuChjfCJxfUyCRMNWtm2W5ygTc7vV7mK4N22tGpump', CAST('2026-06-06T22:55:54Z' AS TIMESTAMPTZ), CAST('424771436' AS BIGINT), 574)) AS _values), dl(d) AS (SELECT * FROM (VALUES (30), (120), (300)) AS _values), cp AS (SELECT base_mint AS mint, MIN(pool) AS pool, MAX(base_mint_decimals) AS bd, MAX(quote_mint_decimals) AS qd FROM pumpdotfun_solana.pump_amm_evt_createpoolevent WHERE evt_block_date BETWEEN CAST('2026-06-01' AS DATE) AND CAST('2026-07-10' AS DATE) AND base_mint IN (SELECT mint FROM ev) AND evt_outer_executing_account = '6EF8rrecthR5Dkzon8Nwu78hRvfCKubJ14M5uBEwF6P' AND index = 0 GROUP BY 1), curve AS (SELECT t.mint, t.evt_block_time AS ts, 0 AS venue, t.evt_block_slot AS slot, t.evt_tx_index AS txi, t.evt_outer_instruction_index AS oix, COALESCE(t.evt_inner_instruction_index, -1) AS iix, CAST(COALESCE(t.virtual_sol_reserves, t.virtualSolReserves) AS DOUBLE) / 1e9 AS x, CAST(COALESCE(t.virtual_token_reserves, t.virtualTokenReserves) AS DOUBLE) / 1e6 AS y, CAST(t.real_sol_reserves AS DOUBLE) / 1e9 AS xr, COALESCE(CAST(t.fee_basis_points AS DOUBLE), 0) + COALESCE(CAST(t.creator_fee_basis_points AS DOUBLE), 0) AS fee_bps, COALESCE(CAST(t.buyback_fee_basis_points AS DOUBLE), 0) AS extra_fee_bps FROM pumpdotfun_solana.pump_evt_tradeevent AS t JOIN ev AS e ON e.mint = t.mint WHERE t.evt_block_date BETWEEN CAST('2026-06-01' AS DATE) AND CAST('2026-06-17' AS DATE) AND t.mint IN (SELECT mint FROM ev) AND t.evt_block_time >= e.sig_time), pool_raw AS (SELECT pool, evt_block_time AS ts, evt_block_slot AS slot, evt_tx_index AS txi, evt_outer_instruction_index AS oix, COALESCE(evt_inner_instruction_index, -1) AS iix, CAST(pool_quote_token_reserves AS DOUBLE) AS qraw, CAST(pool_base_token_reserves AS DOUBLE) AS braw, CAST(quote_amount_in_with_lp_fee AS DOUBLE) AS dq, -CAST(base_amount_out AS DOUBLE) AS db, COALESCE(CAST(lp_fee_basis_points AS DOUBLE), 0) + COALESCE(CAST(protocol_fee_basis_points AS DOUBLE), 0) + COALESCE(CAST(coin_creator_fee_basis_points AS DOUBLE), 0) AS fee_bps FROM pumpdotfun_solana.pump_amm_evt_buyevent WHERE evt_block_date BETWEEN CAST('2026-06-01' AS DATE) AND CAST('2026-07-10' AS DATE) AND pool IN (SELECT pool FROM cp) UNION ALL SELECT pool, evt_block_time, evt_block_slot, evt_tx_index, evt_outer_instruction_index, COALESCE(evt_inner_instruction_index, -1), CAST(pool_quote_token_reserves AS DOUBLE), CAST(pool_base_token_reserves AS DOUBLE), -(CAST(quote_amount_out AS DOUBLE) - COALESCE(CAST(lp_fee AS DOUBLE), 0)), CAST(base_amount_in AS DOUBLE), COALESCE(CAST(lp_fee_basis_points AS DOUBLE), 0) + COALESCE(CAST(protocol_fee_basis_points AS DOUBLE), 0) + COALESCE(CAST(coin_creator_fee_basis_points AS DOUBLE), 0) FROM pumpdotfun_solana.pump_amm_evt_sellevent WHERE evt_block_date BETWEEN CAST('2026-06-01' AS DATE) AND CAST('2026-07-10' AS DATE) AND pool IN (SELECT pool FROM cp)), pool_states AS (SELECT c.mint, r.ts, 1 AS venue, r.slot, r.txi, r.oix, r.iix, COALESCE(LEAD(r.qraw) OVER (PARTITION BY r.pool ORDER BY r.slot, r.txi, r.oix, r.iix), r.qraw + r.dq) / POWER(10, c.qd) AS x, COALESCE(LEAD(r.braw) OVER (PARTITION BY r.pool ORDER BY r.slot, r.txi, r.oix, r.iix), r.braw + r.db) / POWER(10, c.bd) AS y, CAST(NULL AS DOUBLE) AS xr, r.fee_bps, CAST(0 AS DOUBLE) AS extra_fee_bps FROM pool_raw AS r JOIN cp AS c ON c.pool = r.pool), states AS (SELECT s.* FROM (SELECT * FROM curve UNION ALL SELECT * FROM pool_states) AS s JOIN ev AS e ON e.mint = s.mint WHERE s.ts >= e.sig_time AND s.x > 0 AND s.y > 0), paths AS (SELECT s.*, e.sig_time, e.sig_slot, e.sig_txi, dl.d, e.sig_time + INTERVAL (dl.d) SECOND AS t_entry, e.sig_time + INTERVAL (dl.d) SECOND + INTERVAL 30 DAY AS t_end, EPOCH(s.ts) AS ts_s, ROW_NUMBER() OVER (PARTITION BY s.mint, dl.d ORDER BY s.slot, s.txi, s.oix, s.iix) AS rn FROM states AS s JOIN ev AS e ON e.mint = s.mint CROSS JOIN dl WHERE s.ts <= e.sig_time + INTERVAL (dl.d) SECOND + INTERVAL 30 DAY), p1 AS (SELECT *, MAX(CASE WHEN ts <= t_entry THEN rn END) OVER (PARTITION BY mint, d) AS entry_rn, MAX(CASE WHEN slot = sig_slot AND txi = sig_txi THEN rn END) OVER (PARTITION BY mint, d) AS sig_rn FROM paths), p2 AS (SELECT *, MAX(CASE WHEN rn = entry_rn THEN x END) OVER (PARTITION BY mint, d) AS ex, MAX(CASE WHEN rn = entry_rn THEN y END) OVER (PARTITION BY mint, d) AS ey, MAX(CASE WHEN rn = entry_rn THEN fee_bps END) OVER (PARTITION BY mint, d) AS efee, MAX(CASE WHEN rn = entry_rn THEN venue END) OVER (PARTITION BY mint, d) AS evenue, MAX(CASE WHEN rn = entry_rn THEN ts END) OVER (PARTITION BY mint, d) AS entry_state_ts, MAX(CASE WHEN rn = sig_rn THEN x / y END) OVER (PARTITION BY mint, d) AS sig_price FROM p1), p3 AS (SELECT *, ey - ex * ey / (ex + 0.5 * (1 - efee / 1e4)) AS tok, (x / y) / (ex / ey) AS pm FROM p2 WHERE rn >= entry_rn), p4 AS (SELECT *, CASE WHEN CASE WHEN venue = 0 AND y > tok THEN (x * y / (y - tok) - x) * (1 - fee_bps / 1e4) WHEN venue = 0 THEN NULL ELSE (x - x * y / (y + tok)) * (1 - fee_bps / 1e4) END IS NULL OR COALESCE(CASE WHEN venue = 0 THEN xr + 0.5 * (1 - efee / 1e4) END, 1e18) IS NULL THEN NULL ELSE LEAST(CASE WHEN venue = 0 AND y > tok THEN (x * y / (y - tok) - x) * (1 - fee_bps / 1e4) WHEN venue = 0 THEN NULL ELSE (x - x * y / (y + tok)) * (1 - fee_bps / 1e4) END, COALESCE(CASE WHEN venue = 0 THEN xr + 0.5 * (1 - efee / 1e4) END, 1e18)) END / 0.5 AS sm, MAX(pm) OVER (PARTITION BY mint, d ORDER BY rn ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS runmax, LEAD(ts_s) OVER (PARTITION BY mint, d ORDER BY rn) AS next_ts_s, CASE WHEN ts_s < MAX(ts_s) OVER (PARTITION BY mint, d ORDER BY rn ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING) THEN 1 ELSE 0 END AS ts_regress FROM p3), p5 AS (SELECT *, ARG_MAX(sm, rn) OVER (PARTITION BY mint, d ORDER BY ts_s RANGE BETWEEN CURRENT ROW AND 5 FOLLOWING) AS sm_exec5, rn > entry_rn AND pm <= 0.5 * CASE WHEN 1.0 IS NULL OR runmax IS NULL THEN NULL ELSE GREATEST(1.0, runmax) END AS stop_hit, COALESCE(next_ts_s, EPOCH(t_end)) - CASE WHEN ts_s IS NULL OR EPOCH(t_entry) IS NULL THEN NULL ELSE GREATEST(ts_s, EPOCH(t_entry)) END > 86400 AS idle_hit FROM p4), agg AS (SELECT mint, d, ANY_VALUE(sig_time) AS sig_time, ANY_VALUE(t_entry) AS t_entry, ANY_VALUE(entry_state_ts) AS entry_state_ts, ANY_VALUE(evenue) AS entry_venue, ANY_VALUE(efee) AS entry_fee_bps, ANY_VALUE((ex / ey) / sig_price) AS entry_over_signal, ANY_VALUE(ex) AS entry_x, MIN(rn) FILTER(WHERE stop_hit OR idle_hit) AS exit_rn, ARG_MIN(CASE WHEN stop_hit THEN sm_exec5 ELSE sm END, rn) FILTER(WHERE stop_hit OR idle_hit) AS exit_v, ARG_MIN(CASE WHEN stop_hit THEN 'stop' ELSE 'idle' END, rn) FILTER(WHERE stop_hit OR idle_hit) AS exit_kind, ARG_MIN(ts, rn) FILTER(WHERE stop_hit OR idle_hit) AS exit_ts, ARG_MIN(venue, rn) FILTER(WHERE stop_hit OR idle_hit) AS exit_venue, ARG_MIN(runmax, rn) FILTER(WHERE stop_hit OR idle_hit) AS runmax_at_exit, ARG_MAX(sm, rn) AS sm_last, MAX(ts) AS last_ts, MAX(pm) AS max_pm_30d, MAX(runmax) AS runmax_all, MAX(CASE WHEN venue = 0 THEN ts END) AS last_curve_ts, MAX(CASE WHEN venue = 1 THEN ts END) AS last_pool_ts, COUNT(*) AS n_states, SUM(ts_regress) AS n_ts_regress, COUNT_IF(sm IS NULL) AS n_null_sm, MAX(extra_fee_bps) AS max_extra_fee_bps FROM p5 GROUP BY 1, 2) SELECT a.mint, a.d, a.sig_time, a.t_entry, a.entry_state_ts, a.entry_venue, a.entry_fee_bps, a.entry_over_signal, a.entry_x, COALESCE(a.exit_kind, 'horizon') AS exit_kind, COALESCE(a.exit_ts, a.last_ts) AS exit_ts, DATE_DIFF('SECOND', a.t_entry, COALESCE(a.exit_ts, a.last_ts)) / 3600.0 AS hold_h, a.exit_venue, ROUND(COALESCE(a.exit_v, a.sm_last, POWER(1 - a.entry_fee_bps / 1e4, 2)), 6) AS recovery, a.exit_v IS NULL AND NOT a.exit_rn IS NULL AS exit_value_missing, COALESCE(a.runmax_at_exit, a.runmax_all) AS runmax_at_exit, a.max_pm_30d, a.n_states, a.n_ts_regress, a.n_null_sm, a.max_extra_fee_bps, a.last_curve_ts, a.last_pool_ts, a.last_curve_ts >= CAST('2026-06-17T00:00:00Z' AS TIMESTAMPTZ) AND COALESCE(a.last_pool_ts < CAST('2026-06-17T00:00:00Z' AS TIMESTAMPTZ), TRUE) AND COALESCE(a.exit_ts, a.last_ts) >= CAST('2026-06-17T00:00:00Z' AS TIMESTAMPTZ) - INTERVAL '1' DAY AS curve_cut_risk FROM agg AS a ORDER BY a.sig_time, a.mint, a.d
